# Looking more systematically at what happens
inputs = ['bwaky', 'ze', 'fduv', 'wzug', 'yxjib']
outputs = ['befbkvidk', 'zavb', 'fduv', 'wzug', 'vidkxjib']

print("Detailed character-by-character analysis:")

for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"\n{i}: '{inp}' -> '{out}'")

    # Find where they differ
    min_len = min(len(inp), len(out))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != out[j]:
            diff_positions.append((j, inp[j], out[j]))

    # Check if there are extra characters at the end
    if len(inp) < len(out):
        for j in range(len(inp), len(out)):
            diff_positions.append((j, '-', out[j]))
    elif len(inp) > len(out):
        for j in range(len(out), len(inp)):
            diff_positions.append((j, inp[j], '-'))

    print(f"  Differences at positions: {diff_positions}")

